#!/bin/sh
# Data/Request, ordinary Capability, Broadcast and Decision slices. Full
# API/facility/Corpus parity and non-yielding concurrent admission remain
# later gates.
set -eu
cd "$(dirname "$0")"
selection='^(TestZigBackend.*|TestOverrideTraceUsesCatalogueWaitName|TestBroadcastSelectsRecipientsAtDrain|TestBroadcastAcceptedPastMailboxCapacity|TestBroadcastPendingWaitAndPriorCancellation|TestBroadcastDecisionReportsVetoesInRecipientOrderAcrossSlices|TestBroadcastDecisionCancellationRemovesEveryQueuedRecipient|TestBroadcastCancellationPreservesSealedRecipientRun|TestBroadcastDecisionEmptySettlesAtPump|TestDecisionVetoCompletesFinallyBeforeSealing|TestDecisionFirstWaitSealsAcrossPreemptionAndIgnoresLaterCancellation|TestDecisionFailuresRemainUndecided|TestDecisionOrdinaryClauseAllowsBeforeLaterError|TestDecisionOrdinaryClauseCannotAllowUnpaidDispatch|TestDecisionCancelledInMailboxOrPreemptedSegment|TestDecisionDroppingIsUndecidedAndReplacementPreservesSealedVerdict|TestConcurrentBroadcastAdmission|TestRequestExecutionAndWorkerRefusals|TestFailedInitialiserHasItsInstructionPosition|TestMailboxReservationIncludesQueuedInputs|TestSliceDebtAndPumpRoundRobin|TestPumpAcceptsClockBoundariesAndRefusesDecrease|TestWaitReleasesScriptAndResumesAfterInputs|TestRunawayScriptFaultPreservesOtherScriptsAndCommittedSegments|TestWaitFuelFaultDoesNotChargeOrInstallTimer|TestOverrideRejectsUnknownPresenceBits|TestCallChargeAndResultConversionBoundaries|TestOperationValidFailureData|TestOperationFailureConversionLimits|TestSuspendingOperationQueuesAnAnswerDuringStart|TestSuspendingOperationWorkerSettlementsAndRevocation|TestSuspendingOperationFailuresAndResumeLimits|TestSuspendingOperationTimeoutAndCancellation|TestCapabilityJoinUsesMemberDeadlinesAndFirstFailure|TestCapabilityJoinKeepsEarlySettlementsAcrossBodyPreemption|TestLateCapabilityFaultPreservesEarlierSegments|TestCapabilityReadyAnswerRetentionAndCap|TestCancelRunAtStartRollsBackAndAbandons|TestSuspendingPrechargeAndRetentionFaults|TestImmediateAndFireOperations|TestCapabilityFailuresAndPrechargeChecks|TestCapabilityDeclaredAllocationIsAtomic|TestCapabilityLoadChecksAndCompileCache|TestGrantReleaseStopAndRevocation|TestGrantReleasePanicAndQueuedInputs|TestGrantReleaseUsesTrimmedGrants)$'
exec go test -tags talk_zig_experimental -run "$selection" -count=1 "$@" .
